 const signature=JSON.stringify([ids,Array.from(selected),site]);if(signature!==teamKey){teamKey=signature;$('field-team').innerHTML=ids.slice(0,48).map(id=>'<button type="button" class="field-team-beetle" data-field-select="'+id+'" aria-pressed="'+selected.has(id)+'" aria-label="'+esc((selected.has(id)?'Remove ':'Select ')+label(id))+'">'+B.draw(s.beetles[id],'field-team')+'<span>'+esc(label(id))+'</span><small>'+esc(id)+' · '+(s.collection.includes(id)?'Keep':s.nursery.includes(id)?'Nursery':'Breeder')+'</small></button>').join('')||'<p class="hint">No available beetles here. Try the other tank, or move a parent out of its jar.</p>';}
