function paint(kind,agents){const layer=document.querySelector(kind==='tank'?'#tank .habitat-layer':'#keep-tank .habitat-layer');if(!layer)return;const bending=new Map(agents.filter(a=>!a.away&&a.behavior?.drama?.kind==='leaf').map(a=>[a.behavior.drama.objectId,{load:a.behavior.drama.load,held:a.held}]));for(const el of layer.children){const event=bending.get(el.dataset.habitatObject);el.classList.toggle('field-leaf-bending',Boolean(event));el.classList.toggle('field-leaf-paused',Boolean(event?.held));el.style.setProperty('--leaf-load',String(event?.load||0));}}
$('field-sites').innerHTML=Object.entries(F.sites).map(([key,s])=>'<button type="button" data-field-site="'+key+'" aria-pressed="'+(key===site)+'"><strong>'+esc(s.name)+'</strong><span>'+s.duration+' seconds · '+(key==='log'?'gaps, grip & bark':key==='garden'?'stems, sensing & seeds':'routes, tunnels & patience')+'</span></button>').join('');
$('field-sites').onclick=e=>{const b=e.target.closest('[data-field-site]');if(b){site=b.dataset.fieldSite;teamKey='';renderTeam();}};
